create table public.project_assumptions(
 id uuid primary key default gen_random_uuid(),project_id uuid not null references public.projects(id) on delete restrict,
 title text not null,description text not null,category text not null,planning_rationale text not null,validation_method text not null,impact_if_false text not null,confidence text not null,
 owner_membership_id uuid not null references public.project_members(id) on delete restrict,recorded_date date not null default current_date,validation_due_date date not null,
 status text not null default 'Active',validation_evidence text,outcome_notes text,
 validated_by uuid references public.profiles(id) on delete restrict,validated_at timestamptz,invalidated_by uuid references public.profiles(id) on delete restrict,invalidated_at timestamptz,retired_by uuid references public.profiles(id) on delete restrict,retired_at timestamptz,
 created_by uuid not null references public.profiles(id) on delete restrict,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 constraint project_assumptions_title_check check(char_length(btrim(title)) between 1 and 200),
 constraint project_assumptions_description_check check(char_length(btrim(description)) between 1 and 4000),
 constraint project_assumptions_category_check check(category in('Scope','Schedule','Cost','Resources','Technical','Quality','Supplier','Compliance','Operational','Other')),
 constraint project_assumptions_rationale_check check(char_length(btrim(planning_rationale)) between 1 and 4000),constraint project_assumptions_method_check check(char_length(btrim(validation_method)) between 1 and 4000),constraint project_assumptions_impact_check check(char_length(btrim(impact_if_false)) between 1 and 4000),
 constraint project_assumptions_confidence_check check(confidence in('Low','Medium','High')),constraint project_assumptions_dates_check check(validation_due_date>=recorded_date),constraint project_assumptions_status_check check(status in('Active','Under Validation','Validated','Invalidated','Retired')),
 constraint project_assumptions_evidence_check check(validation_evidence is null or char_length(btrim(validation_evidence)) between 1 and 4000),constraint project_assumptions_notes_check check(outcome_notes is null or char_length(btrim(outcome_notes)) between 1 and 4000),
 constraint project_assumptions_state_check check(
  (status in('Active','Under Validation') and outcome_notes is null and validated_by is null and validated_at is null and invalidated_by is null and invalidated_at is null and retired_by is null and retired_at is null) or
  (status='Validated' and validation_evidence is not null and outcome_notes is not null and validated_by is not null and validated_at is not null and invalidated_by is null and invalidated_at is null and retired_by is null and retired_at is null) or
  (status='Invalidated' and validation_evidence is not null and outcome_notes is not null and invalidated_by is not null and invalidated_at is not null and validated_by is null and validated_at is null and retired_by is null and retired_at is null) or
  (status='Retired' and outcome_notes is not null and retired_by is not null and retired_at is not null and validated_by is null and validated_at is null and invalidated_by is null and invalidated_at is null)));
create index project_assumptions_project_status_due_idx on public.project_assumptions(project_id,status,validation_due_date,id);create index project_assumptions_project_owner_status_idx on public.project_assumptions(project_id,owner_membership_id,status);create index project_assumptions_project_confidence_due_idx on public.project_assumptions(project_id,confidence,validation_due_date,id);
create function private.assumption_owner_is_eligible(p_project_id uuid,p_membership_id uuid)returns boolean language sql stable security definer set search_path='' as $$select exists(select 1 from public.project_members pm join public.projects p on p.id=pm.project_id join public.organization_members om on om.organization_id=p.organization_id and om.user_id=pm.user_id and om.status='Active' where pm.id=p_membership_id and pm.project_id=p_project_id and pm.left_at is null and(pm.access_level='Project Member' or(pm.access_level='Project Manager' and pm.user_id=p.project_manager_id)))$$;
create function private.protect_project_assumption()returns trigger language plpgsql security definer set search_path='' as $$begin if tg_op='INSERT' then if new.status<>'Active' or new.created_by<>auth.uid() or new.recorded_date>current_date or new.outcome_notes is not null or new.validated_by is not null or new.validated_at is not null or new.invalidated_by is not null or new.invalidated_at is not null or new.retired_by is not null or new.retired_at is not null then raise exception 'New assumptions must use trusted initial values.' using errcode='23514';end if;else if new.id is distinct from old.id or new.project_id is distinct from old.project_id or new.recorded_date is distinct from old.recorded_date or new.created_by is distinct from old.created_by or new.created_at is distinct from old.created_at then raise exception 'Assumption identity fields cannot be changed.' using errcode='42501';end if;if old.status in('Validated','Invalidated','Retired') then raise exception 'Terminal assumptions cannot be changed.' using errcode='42501';end if;end if;new.title:=btrim(new.title);new.description:=btrim(new.description);new.planning_rationale:=btrim(new.planning_rationale);new.validation_method:=btrim(new.validation_method);new.impact_if_false:=btrim(new.impact_if_false);new.validation_evidence:=nullif(btrim(new.validation_evidence),'');new.outcome_notes:=nullif(btrim(new.outcome_notes),'');new.updated_at:=now();return new;end;$$;
create trigger project_assumptions_protect before insert or update on public.project_assumptions for each row execute function private.protect_project_assumption();alter table public.project_assumptions enable row level security;create policy project_assumptions_select_project_access on public.project_assumptions for select to authenticated using(private.has_project_access(project_id));revoke all on public.project_assumptions from anon,authenticated;grant select on public.project_assumptions to authenticated;
create function public.create_project_assumption(p_project_id uuid,p_title text,p_description text,p_category text,p_planning_rationale text,p_validation_method text,p_impact_if_false text,p_confidence text,p_owner_membership_id uuid,p_recorded_date date,p_validation_due_date date,p_validation_evidence text default null)returns public.project_assumptions language plpgsql security definer set search_path='' as $$declare persisted public.project_assumptions%rowtype;begin if auth.uid() is null or not private.can_manage_project(p_project_id) then raise exception 'Assumption creation is not permitted.' using errcode='42501';end if;if p_recorded_date>current_date then raise exception 'Recorded date cannot be in the future.' using errcode='22023';end if;if not private.assumption_owner_is_eligible(p_project_id,p_owner_membership_id) then raise exception 'The selected assumption owner is not eligible.' using errcode='23514';end if;insert into public.project_assumptions(project_id,title,description,category,planning_rationale,validation_method,impact_if_false,confidence,owner_membership_id,recorded_date,validation_due_date,validation_evidence,created_by)values(p_project_id,p_title,p_description,p_category,p_planning_rationale,p_validation_method,p_impact_if_false,p_confidence,p_owner_membership_id,p_recorded_date,p_validation_due_date,p_validation_evidence,auth.uid())returning * into persisted;return persisted;end;$$;
create function public.update_project_assumption(p_assumption_id uuid,p_title text,p_description text,p_category text,p_planning_rationale text,p_validation_method text,p_impact_if_false text,p_confidence text,p_owner_membership_id uuid,p_validation_due_date date,p_validation_evidence text)returns public.project_assumptions language plpgsql security definer set search_path='' as $$declare current_assumption public.project_assumptions%rowtype;persisted public.project_assumptions%rowtype;begin if auth.uid() is null then raise exception 'Authentication is required.' using errcode='42501';end if;select * into current_assumption from public.project_assumptions where id=p_assumption_id for update;if current_assumption.id is null or not private.can_manage_project(current_assumption.project_id) or current_assumption.status in('Validated','Invalidated','Retired') then raise exception 'Assumption update is not permitted.' using errcode='42501';end if;if not private.assumption_owner_is_eligible(current_assumption.project_id,p_owner_membership_id) then raise exception 'The selected assumption owner is not eligible.' using errcode='23514';end if;update public.project_assumptions set title=p_title,description=p_description,category=p_category,planning_rationale=p_planning_rationale,validation_method=p_validation_method,impact_if_false=p_impact_if_false,confidence=p_confidence,owner_membership_id=p_owner_membership_id,validation_due_date=p_validation_due_date,validation_evidence=p_validation_evidence where id=p_assumption_id returning * into persisted;return persisted;end;$$;
create function public.transition_project_assumption_active(p_assumption_id uuid,p_target_status text)returns public.project_assumptions language plpgsql security definer set search_path='' as $$declare a public.project_assumptions%rowtype;persisted public.project_assumptions%rowtype;begin if auth.uid() is null then raise exception 'Authentication is required.' using errcode='42501';end if;select * into a from public.project_assumptions where id=p_assumption_id for update;if a.id is null or not private.can_manage_project(a.project_id) or a.status not in('Active','Under Validation') then raise exception 'Assumption transition is not permitted.' using errcode='42501';end if;if not((a.status='Active' and p_target_status='Under Validation')or(a.status='Under Validation' and p_target_status='Active'))then raise exception 'Unsupported assumption transition.' using errcode='22023';end if;update public.project_assumptions set status=p_target_status where id=p_assumption_id returning * into persisted;return persisted;end;$$;
create function public.validate_project_assumption(p_assumption_id uuid,p_validation_evidence text,p_outcome_notes text)returns public.project_assumptions language plpgsql security definer set search_path='' as $$declare a public.project_assumptions%rowtype;persisted public.project_assumptions%rowtype;begin if auth.uid() is null then raise exception 'Authentication is required.' using errcode='42501';end if;select * into a from public.project_assumptions where id=p_assumption_id for update;if a.id is null or not private.can_manage_project(a.project_id) or a.status not in('Active','Under Validation')then raise exception 'Assumption validation is not permitted.' using errcode='42501';end if;if nullif(btrim(p_validation_evidence),'')is null or nullif(btrim(p_outcome_notes),'')is null then raise exception 'Meaningful evidence and outcome notes are required.' using errcode='22023';end if;update public.project_assumptions set status='Validated',validation_evidence=btrim(p_validation_evidence),outcome_notes=btrim(p_outcome_notes),validated_by=auth.uid(),validated_at=now()where id=p_assumption_id returning * into persisted;return persisted;end;$$;
create function public.invalidate_project_assumption(p_assumption_id uuid,p_validation_evidence text,p_outcome_notes text)returns public.project_assumptions language plpgsql security definer set search_path='' as $$declare a public.project_assumptions%rowtype;persisted public.project_assumptions%rowtype;begin if auth.uid() is null then raise exception 'Authentication is required.' using errcode='42501';end if;select * into a from public.project_assumptions where id=p_assumption_id for update;if a.id is null or not private.can_manage_project(a.project_id) or a.status not in('Active','Under Validation')then raise exception 'Assumption invalidation is not permitted.' using errcode='42501';end if;if nullif(btrim(p_validation_evidence),'')is null or nullif(btrim(p_outcome_notes),'')is null then raise exception 'Meaningful evidence and outcome notes are required.' using errcode='22023';end if;update public.project_assumptions set status='Invalidated',validation_evidence=btrim(p_validation_evidence),outcome_notes=btrim(p_outcome_notes),invalidated_by=auth.uid(),invalidated_at=now()where id=p_assumption_id returning * into persisted;return persisted;end;$$;
create function public.retire_project_assumption(p_assumption_id uuid,p_outcome_notes text)returns public.project_assumptions language plpgsql security definer set search_path='' as $$declare a public.project_assumptions%rowtype;persisted public.project_assumptions%rowtype;begin if auth.uid() is null then raise exception 'Authentication is required.' using errcode='42501';end if;select * into a from public.project_assumptions where id=p_assumption_id for update;if a.id is null or not private.can_manage_project(a.project_id) or a.status not in('Active','Under Validation')then raise exception 'Assumption retirement is not permitted.' using errcode='42501';end if;if nullif(btrim(p_outcome_notes),'')is null then raise exception 'Meaningful outcome notes are required.' using errcode='22023';end if;update public.project_assumptions set status='Retired',outcome_notes=btrim(p_outcome_notes),retired_by=auth.uid(),retired_at=now()where id=p_assumption_id returning * into persisted;return persisted;end;$$;
create function public.get_project_assumptions(p_project_id uuid)returns table(id uuid,project_id uuid,title text,description text,category text,planning_rationale text,validation_method text,impact_if_false text,confidence text,owner_membership_id uuid,owner_user_id uuid,owner_name text,owner_access_level text,owner_is_eligible boolean,recorded_date date,validation_due_date date,status text,validation_evidence text,outcome_notes text,validated_by uuid,validated_at timestamptz,validated_by_name text,invalidated_by uuid,invalidated_at timestamptz,invalidated_by_name text,retired_by uuid,retired_at timestamptz,retired_by_name text,created_by uuid,created_by_name text,created_at timestamptz,updated_at timestamptz)language sql stable security definer set search_path='' as $$select a.id,a.project_id,a.title,a.description,a.category,a.planning_rationale,a.validation_method,a.impact_if_false,a.confidence,a.owner_membership_id,pm.user_id,op.full_name,pm.access_level,private.assumption_owner_is_eligible(a.project_id,a.owner_membership_id),a.recorded_date,a.validation_due_date,a.status,a.validation_evidence,a.outcome_notes,a.validated_by,a.validated_at,vp.full_name,a.invalidated_by,a.invalidated_at,ip.full_name,a.retired_by,a.retired_at,tp.full_name,a.created_by,cp.full_name,a.created_at,a.updated_at from public.project_assumptions a join public.project_members pm on pm.id=a.owner_membership_id join public.profiles op on op.id=pm.user_id join public.profiles cp on cp.id=a.created_by left join public.profiles vp on vp.id=a.validated_by left join public.profiles ip on ip.id=a.invalidated_by left join public.profiles tp on tp.id=a.retired_by where a.project_id=p_project_id and private.has_project_access(p_project_id) order by case when a.status in('Validated','Invalidated','Retired')then 1 else 0 end,case when a.status in('Active','Under Validation')and not private.assumption_owner_is_eligible(a.project_id,a.owner_membership_id)then 0 else 1 end,case when a.status in('Active','Under Validation')and a.validation_due_date<current_date then 0 else 1 end,case when a.status in('Active','Under Validation')and a.validation_due_date=current_date then 0 else 1 end,case when a.status='Under Validation'then 0 else 1 end,case a.confidence when'Low'then 0 when'Medium'then 1 else 2 end,a.validation_due_date,case when a.status in('Validated','Invalidated','Retired')then coalesce(a.validated_at,a.invalidated_at,a.retired_at)end desc,a.created_at,a.id$$;
create function public.get_eligible_assumption_owners(p_project_id uuid)returns table(membership_id uuid,user_id uuid,full_name text,access_level text)language plpgsql stable security definer set search_path='' as $$begin if auth.uid() is null or not private.can_manage_project(p_project_id)then raise exception 'Assumption management is not permitted.' using errcode='42501';end if;return query select pm.id,pm.user_id,pr.full_name,pm.access_level from public.project_members pm join public.profiles pr on pr.id=pm.user_id join public.projects p on p.id=pm.project_id join public.organization_members om on om.organization_id=p.organization_id and om.user_id=pm.user_id and om.status='Active' where pm.project_id=p_project_id and pm.left_at is null and(pm.access_level='Project Member'or(pm.access_level='Project Manager'and pm.user_id=p.project_manager_id))order by pr.full_name,pm.id;end;$$;
revoke all on function private.assumption_owner_is_eligible(uuid,uuid),private.protect_project_assumption()from public;revoke all on function public.create_project_assumption(uuid,text,text,text,text,text,text,text,uuid,date,date,text),public.update_project_assumption(uuid,text,text,text,text,text,text,text,uuid,date,text),public.transition_project_assumption_active(uuid,text),public.validate_project_assumption(uuid,text,text),public.invalidate_project_assumption(uuid,text,text),public.retire_project_assumption(uuid,text),public.get_project_assumptions(uuid),public.get_eligible_assumption_owners(uuid)from public;grant execute on function public.create_project_assumption(uuid,text,text,text,text,text,text,text,uuid,date,date,text),public.update_project_assumption(uuid,text,text,text,text,text,text,text,uuid,date,text),public.transition_project_assumption_active(uuid,text),public.validate_project_assumption(uuid,text,text),public.invalidate_project_assumption(uuid,text,text),public.retire_project_assumption(uuid,text),public.get_project_assumptions(uuid),public.get_eligible_assumption_owners(uuid)to authenticated;
